<template><ion-page><ion-header><ion-toolbar><ion-buttons slot="start"><ion-back-button default-href="/app/home"/></ion-buttons><ion-title>Detalhes</ion-title><ion-buttons v-if="album" slot="end"><ion-button @click="toggleFavorite(album.id)"><ion-icon slot="icon-only" :icon="album.favorite?heart:heartOutline"/></ion-button></ion-buttons></ion-toolbar></ion-header><ion-content><main v-if="album" class="detail-page"><section class="detail-cover" :style="{background:gradient}"><span>{{album.year}}</span><ion-icon :icon="disc"/><b>REC</b></section><section class="detail-info"><p class="page-kicker">Álbum · {{album.songs.length}} faixas</p><h1>{{album.name}}</h1><p class="detail-artist">{{album.artist}}</p><div class="detail-actions"><ion-button shape="round"><ion-icon slot="start" :icon="play"/>Reproduzir</ion-button><ion-button fill="outline" shape="round" @click="toggleFavorite(album.id)"><ion-icon slot="icon-only" :icon="album.favorite?heart:heartOutline"/></ion-button></div><h2>Tracklist</h2><ol><li v-for="(song,i) in album.songs" :key="song"><span>{{String(i+1).padStart(2,'0')}}</span><b>{{song}}</b><small>—:—</small></li></ol></section></main><div v-else class="empty"><h2>Álbum não encontrado</h2></div></ion-content></ion-page></template><script setup lang="ts">import{computed}from'vue';import{useRoute}from'vue-router';import{IonBackButton,IonButton,IonButtons,IonContent,IonHeader,IonIcon,IonPage,IonTitle,IonToolbar}from'@ionic/vue';import{disc,heart,heartOutline,play}from'ionicons/icons';import{getAlbum,toggleFavorite}from'@/services/storage';const route=useRoute(),album=computed(()=>getAlbum(route.params.id as string)),n=computed(()=>[...(album.value?.name||'REC')].reduce((s,c)=>s+c.charCodeAt(0),0)),gradient=computed(()=>`linear-gradient(145deg,hsl(${n.value%360} 72% 58%),hsl(${(n.value+65)%360} 65% 25%))`);</script><style scoped>.detail-page{width:min(calc(100% - 40px),1050px);margin:auto;padding:55px 0 110px;display:grid;grid-template-columns:minmax(280px,430px) 1fr;gap:clamp(35px,7vw,90px);align-items:start}.detail-cover{position:sticky;top:80px;aspect-ratio:1;border-radius:30px;display:grid;place-items:center;box-shadow:0 35px 90px #000a;overflow:hidden}.detail-cover:after{content:'';position:absolute;inset:0;background:linear-gradient(#fff2,transparent,#0005)}.detail-cover>ion-icon{font-size:45%;color:#ffffffe6}.detail-cover span,.detail-cover b{position:absolute;z-index:2;font-size:.7rem;letter-spacing:.2em}.detail-cover span{left:25px;bottom:24px}.detail-cover b{left:25px;top:24px}.detail-info{padding-top:20px}.detail-info h1{font-size:clamp(3rem,7vw,6rem);line-height:.9;letter-spacing:-.07em;margin:12px 0}.detail-artist{color:#a5aa9f;font-size:1.25rem}.detail-actions{display:flex;gap:10px;margin:28px 0 48px}.detail-info h2{letter-spacing:-.04em}ol{list-style:none;padding:0;border-top:1px solid #ffffff14}li{display:grid;grid-template-columns:40px 1fr auto;gap:12px;padding:18px 4px;border-bottom:1px solid #ffffff14;align-items:center}li span,li small{color:#73786f;font-size:.75rem}li b{font-size:.95rem}@media(max-width:760px){.detail-page{grid-template-columns:1fr;padding-top:24px}.detail-cover{position:relative;top:auto}.detail-info h1{font-size:3rem}}</style>